"""Single-rook escape map: verify g(r,p) is always a safe king step."""
from __future__ import annotations
from typing import Tuple

Sq = Tuple[int, int]


def esc(a: int, c: int) -> int:
    return a - 1 if c == a + 1 else a + 1


def g_step(r: Sq, p: Sq) -> Sq:
    return (esc(p[0], r[0]), esc(p[1], r[1]))


def king_adj(p: Sq, q: Sq) -> bool:
    return p != q and abs(p[0] - q[0]) <= 1 and abs(p[1] - q[1]) <= 1


def rook_attacks(r: Sq, s: Sq) -> bool:
    return s != r and (s[0] == r[0] or s[1] == r[1])


if __name__ == "__main__":
    for r, p in [((0, 0), (3, 5)), ((2, 2), (2, 7)), ((5, 5), (5, 5))]:
        d = g_step(r, p)
        assert king_adj(p, d) and not rook_attacks(r, d)
        print(f"rook={r} king={p} -> {d}: adjacent & safe")
    print("Every escape step is a legal, unattacked king move.")

"""Infinite escape run: iterate the escape map and watch distance grow."""
from __future__ import annotations
from typing import Tuple

Sq = Tuple[int, int]


def esc(a: int, c: int) -> int:
    return a - 1 if c == a + 1 else a + 1


def g_step(r: Sq, p: Sq) -> Sq:
    return (esc(p[0], r[0]), esc(p[1], r[1]))


def cheb(a: Sq, b: Sq) -> int:
    return max(abs(a[0] - b[0]), abs(a[1] - b[1]))


if __name__ == "__main__":
    r, p = (0, 0), (2, 3)
    for n in range(12):
        p = g_step(r, p)
        print(f"move {n+1:>2}: king={p}  dist-to-rook={cheb(p, r)}")
    print("Distance is unbounded: the king escapes forever.")

"""Two rooks cannot mate: exhaustive search over a local window."""
from __future__ import annotations
from itertools import product
from typing import Iterable, List, Tuple

Sq = Tuple[int, int]


def rook_attacks(r: Sq, s: Sq) -> bool:
    return s != r and (s[0] == r[0] or s[1] == r[1])


def attacked_by(army: Iterable[Sq], s: Sq) -> bool:
    return any(rook_attacks(r, s) for r in army)


def neighbours(k: Sq) -> List[Sq]:
    return [(k[0] + dx, k[1] + dy)
            for dx, dy in product((-1, 0, 1), repeat=2) if (dx, dy) != (0, 0)]


def checkmated(army: List[Sq], k: Sq) -> bool:
    return attacked_by(army, k) and all(attacked_by(army, s) for s in neighbours(k))


if __name__ == "__main__":
    k = (0, 0)
    cells = [(x, y) for x, y in product(range(-3, 4), range(-3, 4)) if (x, y) != k]
    mates = sum(
        checkmated([cells[i], cells[j]], k)
        for i in range(len(cells)) for j in range(i + 1, len(cells))
    )
    print(f"checkmates by two rooks in 7x7 window: {mates}  (theory: 0)")
    assert mates == 0

"""Safe squares: a finite army leaves infinitely many unattacked squares."""
from __future__ import annotations
from itertools import product
from typing import Iterable, List, Set, Tuple

Sq = Tuple[int, int]


def rook_attacks(r: Sq, s: Sq) -> bool:
    return s != r and (s[0] == r[0] or s[1] == r[1])


def attacked_by(army: Iterable[Sq], s: Sq) -> bool:
    return any(rook_attacks(r, s) for r in army)


def safe_squares(army: List[Sq], half: int) -> Set[Sq]:
    rng = range(-half, half + 1)
    return {(x, y) for x, y in product(rng, rng) if not attacked_by(army, (x, y))}


if __name__ == "__main__":
    army = [(0, 0), (3, -2), (-4, 5), (7, 7)]
    for half in (5, 10, 20):
        print(f"{2*half+1}x{2*half+1} window: {len(safe_squares(army, half))} safe squares")
    print("Safe-square count grows with the window: infinitely many exist.")

