from itertools import product
from typing import List, Optional, Tuple

Sq = Tuple[int, int]


def free_coordinate(blocked: set, center: int) -> Optional[int]:
    """Among center-1, center, center+1 return one not in `blocked` (size <= 2)."""
    for x in (center - 1, center, center + 1):
        if x not in blocked:
            return x
    return None


def refute_two_rook_mate(rooks: List[Sq], king: Sq) -> Sq:
    """Given at most two rooks giving check, return a safe king-adjacent escape."""
    assert len(rooks) <= 2
    files = {r[0] for r in rooks}
    ranks = {r[1] for r in rooks}
    a, b = king
    # In-check means king's file or rank is blocked; pigeonhole gives a free line.
    if a in files:                       # blocked file -> a free neighbour column
        x = free_coordinate(files, a)    # exists: 3 columns, <=2 blocked
        assert x is not None and x != a
        y = free_coordinate(ranks, b)    # 3 rows, <=2 blocked
        return (x, y)
    else:                                # blocked rank
        y = free_coordinate(ranks, b)
        assert y is not None and y != b
        x = free_coordinate(files, a)
        return (x, y)

