from itertools import count
from typing import Iterable, Iterator, Tuple

Sq = Tuple[int, int]


def safe_squares(rooks: Iterable[Sq]) -> Iterator[Sq]:
    """Lazily yield squares attacked by no rook (infinitely many exist)."""
    rooks = list(rooks)
    files = {r[0] for r in rooks}
    ranks = {r[1] for r in rooks}
    for x in count(0):                    # scan an unbounded set of columns
        if x in files:
            continue
        for y in count(0):
            if y not in ranks:
                yield (x, y)
                break

