"""Heatmap of attacked (dark) vs safe (light) squares for a rook army."""
from __future__ import annotations
import matplotlib.pyplot as plt
import numpy as np
from typing import List, Tuple

Sq = Tuple[int, int]


def rook_attacks(r: Sq, s: Sq) -> bool:
    return s != r and (s[0] == r[0] or s[1] == r[1])


def main() -> None:
    army: List[Sq] = [(0, 0), (3, -2), (-4, 5), (6, 6)]
    half = 12
    grid = np.zeros((2 * half + 1, 2 * half + 1))
    for i, x in enumerate(range(-half, half + 1)):
        for j, y in enumerate(range(-half, half + 1)):
            grid[j, i] = any(rook_attacks(r, (x, y)) for r in army)
    plt.figure(figsize=(6, 6))
    plt.imshow(grid, origin="lower", extent=[-half, half, -half, half], cmap="Greys")
    for r in army:
        plt.scatter([r[0]], [r[1]], c="red", s=90, marker="s")
    plt.title("Finitely many lines miss cofinitely many squares")
    plt.savefig("coverage_heatmap.png", dpi=130, bbox_inches="tight")


if __name__ == "__main__":
    main()
